// Let's scroll down multiple times or check API
const scrollResults = await browserjs(tabId, async () => {
  const container = document.querySelector('.DCCfo.kXP4L');
  if (!container) return { error: "no container" };

  let lastCount = 0;
  let stagnantTurns = 0;
  const loadedPosts = [];

  for (let i = 0; i < 15; i++) {
    container.scrollTop = container.scrollHeight;
    await new Promise(r => setTimeout(r, 1500));

    const articles = Array.from(container.querySelectorAll('article'));
    if (articles.length === lastCount) {
      stagnantTurns++;
      if (stagnantTurns >= 3) break;
    } else {
      stagnantTurns = 0;
      lastCount = articles.length;
    }
  }

  const finalArticles = Array.from(container.querySelectorAll('article'));
  return {
    totalArticles: finalArticles.length,
    articles: finalArticles.map((art, idx) => {
      const links = Array.from(art.querySelectorAll('a')).map(a => ({ text: a.innerText.trim(), href: a.href }));
      return {
        idx: idx + 1,
        text: art.innerText.trim(),
        links
      };
    })
  };
});

